        // Request bit 3 to set pointer to bit 0.
        req = arb_seq_item::type_id::create("req");
        start_item(req);
        req.randomize() with { rst_n == 1'b1; req == 4'b1000; };
        finish_item(req);
        
        // Then request bit 2. Pointer is 0001, request is 0100.
        req = arb_seq_item::type_id::create("req");
        start_item(req);
        req.randomize() with { rst_n == 1'b1; req == 4'b0100; };
        finish_item(req);
