// ------------------------------------------------------------------------
// Scoreboard: Replicates round-robin arbitration logic as a reference model.
// Tracks transaction counts and reports a summary at end of test.
// ------------------------------------------------------------------------
class arb_scoreboard extends uvm_scoreboard;
    `uvm_component_utils(arb_scoreboard)

    uvm_analysis_imp #(arb_seq_item, arb_scoreboard) ap_imp;

    // Internal state representing the reference model's view of priority_ptr
    logic [3:0] ref_priority_ptr;

    // Statistics counters for end-of-test summary
    int unsigned num_transactions = 0;
    int unsigned num_resets       = 0;
    int unsigned num_checks       = 0;
    int unsigned num_passes       = 0;
    int unsigned num_mismatches   = 0;
    int unsigned num_idle         = 0;  // req == 0 cycles

    function new(string name = "arb_scoreboard", uvm_component parent = null);
        super.new(name, parent);
        ap_imp = new("ap_imp", this);
        // Initialization state matches DUT reset
        ref_priority_ptr = 4'b0001;
    endfunction

    function void build_phase(uvm_phase phase);
        super.build_phase(phase);
        `uvm_info("SCB", "Scoreboard built and ready", UVM_LOW)
    endfunction

    virtual function void write(arb_seq_item tr);
        logic [3:0] exp_grant;
        logic [3:0] mask;
        logic [3:0] masked_req;

        num_transactions++;

        // Reset modeling: re-initialize reference state
        if (!tr.rst_n) begin
            ref_priority_ptr = 4'b0001;
            num_resets++;
            `uvm_info("SCB",
                $sformatf("Reset sampled (txn #%0d). Re-initialized priority pointer.",
                          num_transactions),
                UVM_HIGH)
            return;
        end

        // Idle case (no requests)
        if (tr.req == 4'b0000) begin
            num_idle++;
            if (tr.grant !== 4'b0000) begin
                num_mismatches++;
                `uvm_error("SCB_FAIL",
                    $sformatf("Idle mismatch! req=0, but grant=%b at txn #%0d",
                              tr.grant, num_transactions))
            end else begin
                num_passes++;
                num_checks++;
            end
            return;
        end

        // Reference model calculation matching design intent
        mask = ~(ref_priority_ptr - 1'b1);
        masked_req = tr.req & mask;

        if (masked_req != 4'b0000) begin
            exp_grant = masked_req & (~masked_req + 1'b1);  // Lowest set bit (masked path)
        end else begin
            exp_grant = tr.req & (~tr.req + 1'b1);          // Lowest set bit (wrap-around)
        end

        num_checks++;

        // Correctness Check
        if (exp_grant !== tr.grant) begin
            num_mismatches++;
            `uvm_error("SCB_FAIL",
                $sformatf("MISMATCH @ txn #%0d! req=%b, ptr=%b -> Expected grant=%b, Actual grant=%b",
                          num_transactions, tr.req, ref_priority_ptr, exp_grant, tr.grant))
        end else begin
            num_passes++;
            `uvm_info("SCB_PASS",
                $sformatf("MATCH @ txn #%0d: req=%b ptr=%b -> grant=%b",
                          num_transactions, tr.req, ref_priority_ptr, tr.grant),
                UVM_HIGH)
        end

        // Update Reference Pointer on valid grant
        if (exp_grant != 4'b0000) begin
            ref_priority_ptr = {exp_grant[2:0], exp_grant[3]};  // Left rotate by 1
        end
    endfunction

    // End-of-test summary report
    function void report_phase(uvm_phase phase);
        super.report_phase(phase);
        `uvm_info("SCB_SUMMARY",
            $sformatf("\n========== SCOREBOARD SUMMARY ==========\n  Total transactions : %0d\n  Reset transactions : %0d\n  Active checks      : %0d\n  Idle (req=0)       : %0d\n  Passes             : %0d\n  Mismatches         : %0d\n  Result             : %s\n========================================",
                      num_transactions,
                      num_resets,
                      num_checks,
                      num_idle,
                      num_passes,
                      num_mismatches,
                      (num_mismatches == 0 && num_checks > 0) ? "*** PASS ***" :
                      (num_checks == 0)                       ? "*** NO CHECKS RAN — CHECK MONITOR WIRING ***" :
                                                                "*** FAIL ***"),
            UVM_LOW)
    endfunction
endclass

