// Functional Coverage (uvm_subscriber)
// ════════════════════════════════════════════════════════════

// ------------------------------------------------------------------------
// Functional Coverage: Evaluates stimulus quality and arbitration patterns.
// Reports overall coverage percentage at end of test.
// ------------------------------------------------------------------------
class arb_coverage extends uvm_subscriber #(arb_seq_item);
    `uvm_component_utils(arb_coverage)

    arb_seq_item tr;

    // Sample counter for proof-of-life
    int unsigned num_samples       = 0;
    int unsigned num_active_samples = 0;

    covergroup cg_arb;
        option.per_instance = 1;
        option.name         = "cg_arb";

        // Cover point for requests focusing on corner values
        cp_req: coverpoint tr.req iff (tr.rst_n) {
            bins zero     = {4'b0000};
            bins one_hot[]= {4'b0001, 4'b0010, 4'b0100, 4'b1000};
            bins all_ones = {4'b1111};
            bins multi    = {[1:14]} with ($countones(item) > 1);
        }

        // Cover point for grants focusing on outputs
        cp_grant: coverpoint tr.grant iff (tr.rst_n) {
            bins zero      = {4'b0000};
            bins grant_b0  = {4'b0001};
            bins grant_b1  = {4'b0010};
            bins grant_b2  = {4'b0100};
            bins grant_b3  = {4'b1000};
            illegal_bins non_one_hot = default;  // Catch any non one-hot/non-zero grant
        }

        // Round-robin transition coverage
        cp_grant_trans: coverpoint tr.grant iff (tr.rst_n && (tr.grant != 4'b0000)) {
            bins seq_0_1 = (4'b0001 => 4'b0010);
            bins seq_1_2 = (4'b0010 => 4'b0100);
            bins seq_2_3 = (4'b0100 => 4'b1000);
            bins wrap_3_0= (4'b1000 => 4'b0001);  // Wraparound
            bins seq_0_2 = (4'b0001 => 4'b0100);  // Skip transitions
            bins seq_0_3 = (4'b0001 => 4'b1000);
            bins seq_1_3 = (4'b0010 => 4'b1000);
        }

        // Reset coverage
        cp_rst: coverpoint tr.rst_n {
            bins reset_active   = {1'b0};
            bins reset_inactive = {1'b1};
        }

        // Cross coverage: every request pattern × every grant outcome
        cx_req_grant: cross cp_req, cp_grant {
            // Illegal: zero request must produce zero grant; non-zero req must produce non-zero grant
            illegal_bins ill_zero_req_nonzero_grant =
                binsof(cp_req.zero) && !binsof(cp_grant.zero);
        }
    endgroup

    function new(string name = "arb_coverage", uvm_component parent = null);
        super.new(name, parent);
        cg_arb = new();
    endfunction

    function void build_phase(uvm_phase phase);
        super.build_phase(phase);
        `uvm_info("COV", "Coverage collector built and ready", UVM_LOW)
    endfunction

    virtual function void write(arb_seq_item t);
        tr = t;
        cg_arb.sample();
        num_samples++;
        if (tr.rst_n) num_active_samples++;
    endfunction

    // End-of-test summary report
    function void report_phase(uvm_phase phase);
        real cov_total;
        real cov_req;
        real cov_grant;
        real cov_trans;
        real cov_cross;

        super.report_phase(phase);

        cov_total = cg_arb.get_coverage();
        cov_req   = cg_arb.cp_req.get_coverage();
        cov_grant = cg_arb.cp_grant.get_coverage();
        cov_trans = cg_arb.cp_grant_trans.get_coverage();
        cov_cross = cg_arb.cx_req_grant.get_coverage();

        `uvm_info("COV_SUMMARY",
            $sformatf("\n========== COVERAGE SUMMARY ==========\n  Samples taken      : %0d\n  Active samples     : %0d (rst_n=1)\n  cp_req coverage    : %0.2f%%\n  cp_grant coverage  : %0.2f%%\n  cp_grant_trans     : %0.2f%%\n  cx_req_grant       : %0.2f%%\n  Overall cg_arb     : %0.2f%%\n  Status             : %s\n======================================",
                      num_samples,
                      num_active_samples,
                      cov_req,
                      cov_grant,
                      cov_trans,
                      cov_cross,
                      cov_total,
                      (num_samples == 0)    ? "*** NO SAMPLES — CHECK MONITOR WIRING ***" :
                      (cov_total >= 95.0)   ? "*** GOAL MET (>=95%) ***" :
                      (cov_total >= 75.0)   ? "*** ACCEPTABLE (>=75%) ***" :
                                              "*** LOW COVERAGE — ADD MORE STIMULUS ***"),
            UVM_LOW)
    endfunction
endclass

