// ------------------------------------------------------------------------
// Top-Level Module: Generates clock, instantiates DUT and triggers UVM.
// ------------------------------------------------------------------------
module tb_top;
    `include "uvm_macros.svh"
    import uvm_pkg::*;

    // Default configuration
    parameter int N = 4;

    logic clk;

    // Instantiate provided interface
    arb_if #(N) vif(.clk(clk));

    // Instantiate DUT (SVA is implicitly bound inside design file)
    round_robin_arbiter #(N) dut (
        .clk  (vif.clk),
        .rst_n(vif.rst_n),
        .req  (vif.req),
        .grant(vif.grant)
    );

    // Clock generator (100MHz / 10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

// Pre-UVM initialization to avoid X-propagation on first clock edge
initial begin
    vif.rst_n = 1'b0;
    vif.req   = '0;
    // Hold reset for a few cycles before UVM takes over
    repeat (3) @(posedge clk);
    // Driver will take over from here
end


    // Test initialization
    initial begin
        // Pass virtual interface down to UVM hierarchy
        uvm_config_db#(virtual arb_if #(N))::set(null, "*", "vif", vif);
        
        // Starts execution of the test class registered with UVM factory
        run_test("arb_test");
    end

    // Dumpform handling (useful for debugging, optional)
    initial begin
        $dumpfile("dump.vcd");
        $dumpvars(0, tb_top);
    end

endmodule

